#include <vector>
#include <algorithm>
#include <iterator>

int main() {
    std::vector<int> v = {5, 1, 4, 2, 8};

    // O(1) random access using index
    int x = v[3]; // x = 2

    // Random access iterator arithmetic (O(1))
    auto it1 = v.begin();
    auto it2 = it1 + 4; // Move 4 positions instantly

    // Using algorithm requiring RA iterators
    std::sort(v.begin(), v.end());
}
